@Test
fun `test user login updates state correctly`() = runTest {
    val viewModel = AuthViewModel(fakeAuthRepo)

    viewModel.uiState.test {
        // 1. فحص الحالة الابتدائية فوراً:
        assertEquals(AuthUiState.Idle, awaitItem())

        // تنفيذ الحدث:
        viewModel.login("user", "pass")

        // 2. التحقق من حالة التحميل ثم حالة النجاح بالترتيب:
        assertEquals(AuthUiState.Loading, awaitItem())
        val successState = awaitItem() as AuthUiState.Success
        assertEquals("token_123", successState.token)

        // 3. التأكد من عدم وجود أي انبعاثات غير متوقعة:
        expectNoEvents()
    }
}
